local G=require('genome');local L=require('lab_engineering');local A=require('anatomy');local C=require('cognition');local T=require('living_stats');local I=require('organism_adapter');local S=require('persistence')
return function(B,test)
 local function genome() return G.copy(require('ecology_examples').land.genome) end
 local function organism(s,neural)
  local o=assert(B.spawn(s,genome(),'Engineering test',0,.5,.5));o.maturity=1;o.caps=A.capabilities(o.anatomy,o.genome)
  if neural then for _,p in ipairs(o.anatomy.organs) do if p.type=='Brain' then p.capacity=20;p.efficiency=1 end end;for _,n in ipairs(o.anatomy.nerves) do n.efficiency=1 end;o.caps=A.capabilities(o.anatomy,o.genome) end
  T.updateVitals(o,0);return o
 end
 test('DNA vial generation has persistent reproducible sequence identity',function()
  local a,b=B.new(91),B.new(91);L.starter(a);L.starter(b);assert(#a.lab.vials==3 and a.lab.vials[1].sequence==b.lab.vials[1].sequence and #a.lab.vials[1].sequence==144);assert(a.lab.vials[1].id~=a.lab.vials[2].id);assert(not a.lab.vials[1].sequenced)
  a.lab.vials[1].assay=true;B.update(a,7);assert(a.lab.vials[1].sequenced and a.lab.vials[1].findings.bodySymmetry)
 end)
 test('Genome construction uses six DNA sources with real locus contributions',function()
  local s=B.new(77);local ids={};for i=1,6 do ids[i]=L.buyVial(s,true).id end;local d=assert(L.draft(s,ids));local sources={};for _,chr in ipairs(d.genome.chromosomes) do for _,l in ipairs(chr.loci) do sources[l.sourceA]=true;sources[l.sourceB]=true end end;local n=0;for _ in pairs(sources) do n=n+1 end;assert(n==6 and #d.sources==6 and G.valid(d.genome))
 end)
 test('Deletion, duplication and regulation alter biological expression and development',function()
  local s=B.new(4);local v=L.buyVial(s,true);v.genome=genome();local d=L.draft(s,{v.id});local l=d.genome.chromosomes[16].loci[1];l.a=1;l.b=1;local original=G.value(d.genome,16);local before=A.procedural(d.genome).caps.force
  L.edit(s,d,'duplicate',16,1);assert(G.value(d.genome,16)>original);assert(A.procedural(d.genome).caps.force~=before)
  L.edit(s,d,'delete',16,1);assert(G.value(d.genome,16)==0);L.edit(s,d,'restore',16,1);assert(G.value(d.genome,16)==original)
  d.genome.chromosomes[12].loci[2].a=3;d.genome.chromosomes[12].loci[2].b=3;L.edit(s,d,'regulate',16,1);local activated=G.value(d.genome,16);L.edit(s,d,'regulate',16,1);local suppressed=G.value(d.genome,16);assert(activated>original and suppressed<original)
 end)
 test('Splicing, archive reuse and dosage/regulatory inheritance preserve edited genomes',function()
  local s=B.new(12);L.starter(s);local d=L.draft(s,{s.lab.vials[1].id});L.edit(s,d,'splice',2,1,s.lab.vials[2]);assert(d.genome.chromosomes[2].loci[1].a==s.lab.vials[2].genome.chromosomes[2].loci[1].a);L.edit(s,d,'duplicate',16,1);L.edit(s,d,'regulate',16,1);d.name='Selected synthetic line';assert(L.archive(s,d));local restored=L.restore(s,1);assert(G.hash(restored.genome)==G.hash(d.genome));L.edit(s,restored,'delete',16,1);assert(s.lab.archives[1].genome.chromosomes[16].loci[1].copies==2)
  local a=G.gamete(d.genome,G.rng(4),'A',false);local b=G.gamete(d.genome,G.rng(5),'B',false);local child=assert(G.fertilize(a,b));assert(child.chromosomes[16].loci[1].copies==2 and #child.regulation==1)
 end)
 test('Blank-cell installation completes synthetic embryogenesis without donor-cell ingredients',function()
  local s=B.new(42);local v=L.buyVial(s,true);v.genome=genome();local d=L.draft(s,{v.id});local blanks=s.lab.blankCells;assert(#s.cells==0);assert(L.install(s,d,B,false));assert(s.lab.blankCells==blanks-1 and s.eggs[1].population==1)
  B.update(s,12);assert(s.eggs[1].population>1 and s.eggs[1].nutrientUse>0 and #s.eggs[1].developmentalHistory>1);B.update(s,70);assert(#s.organisms==1 and #s.eggs==0 and s.experiments[1].outcome=='Viable juvenile')
 end)
 test('Batch engineering creates six matching stem cells that enter existing cultivation',function()
  local s=B.new(13);local v=L.buyVial(s,true);local d=L.draft(s,{v.id});assert(L.install(s,d,B,true));assert(#s.cells==6);for _,c in ipairs(s.cells) do assert(c.type==1 and G.hash(c.genome)==G.hash(d.genome)) end;assert(B.cultivate(s,1,1));B.update(s,120);assert(B.harvest(s,1));assert(#s.cells>6)
 end)
 test('Six dynamic stats respond to fatigue, tissue injury and neural condition',function()
  local s=B.new(9);local o=organism(s,true);local healthy=T.calculate(o);o.stamina=10;local fatigued=T.calculate(o);assert(fatigued.END<healthy.END and fatigued.DEX<healthy.DEX);o.stamina=100;A.damage(o.anatomy,'Muscle',.8);A.damage(o.anatomy,'Skin',1);A.damage(o.anatomy,'Brain',.8);o.caps=A.capabilities(o.anatomy,o.genome);local hurt=T.calculate(o);assert(hurt.STR<healthy.STR and hurt.DEF<healthy.DEF and hurt.INT<healthy.INT)
 end)
 test('Blood transport can fail while generic health remains positive',function()
  local s=B.new(10);local o=organism(s,true);assert(o.vitals.cardiac);o.health=100;o.vitals.bloodVolume=0;T.updateVitals(o,.1);assert(not o.alive and o.health==100 and o.deathCause:find('Transport'))
 end)
 test('Continuous nature differs genetically; injury can override aggression',function()
  local s=B.new(7);local a=organism(s,true);local b=organism(s,true);a.genome.chromosomes[8].loci[1].a=0;a.genome.chromosomes[8].loci[1].b=0;b.genome.chromosomes[8].loci[1].a=3;b.genome.chromosomes[8].loci[1].b=3;local na,nb=C.nature(a),C.nature(b);assert(na.sociability>nb.sociability and na.aggression<nb.aggression)
  b.health=10;b.cognition.stress=.9;a.x=b.x+.005;local intent=C.intent(b,s);assert(intent.activity=='Retreating')
 end)
 test('Perception-gated memory reinforces, forgets and respects neural capacity',function()
  local s=B.new(30);local o=organism(s,true);assert(not C.remember(o,{kind='unseen',perceived=false},0));assert(C.remember(o,{kind='food',x=.7,y=.7,outcome=1,perceived=true},0));local first=o.cognition.memories[1].strength;C.remember(o,{kind='food',x=.7,y=.7,outcome=1,perceived=true},1);assert(o.cognition.memories[1].strength>first);o.energy=50;assert(C.intent(o,s).activity=='Revisiting food site')
  s.organisms={};s.time=10000;C.update(o,s,10000);assert(#o.cognition.memories==0);A.damage(o.anatomy,'Brain',1);o.caps=A.capabilities(o.anatomy,o.genome);assert(not C.remember(o,{kind='food',perceived=true},10001))
 end)
 test('Individual recognition and trust require repeated perceived social encounters',function()
  local s=B.new(31);local a=organism(s,true);local b=organism(s,true);b.x=.95;b.y=.9;s.time=4;C.update(a,s,3);assert(a.cognition.relationships[tostring(b.id)]==nil);b.x=a.x+.005;b.y=a.y
  for i=1,20 do s.time=4+i*3;C.update(a,s,3) end;local relation=a.cognition.relationships[tostring(b.id)];assert(relation and relation.encounters>=10 and relation.familiarity>0 and relation.trust>0)
 end)
 test('Communication and future AI intents cannot invent speech or desktop access',function()
  local s=B.new(5);local o=organism(s,true);local event=C.communication(o,'investigate',nil,100);assert(event and not event.capabilities.vocal and not event.capabilities.language);assert(not I.validateIntent(o,{action='speak'}));assert(not I.validateIntent(o,{action='open_file'}));assert(I.validateIntent(o,{action='rest'}));o.caps.flight.powered=false;assert(not I.validateIntent(o,{action='fly'}))
 end)
 test('Manual save and shared organism adapter preserve memories, relationships and laboratory history',function()
  local s=B.new(15);local o=organism(s,true);L.starter(s);local d=L.draft(s,{s.lab.vials[1].id});L.archive(s,d);C.remember(o,{kind='food',perceived=true,outcome=1},s.time);o.cognition.relationships['900']={subject=900,familiarity=.8,trust=.5};local loaded=assert(S.decode('return '..S.encode(s),B));assert(loaded.version==5 and #loaded.lab.archives==1 and #loaded.organisms[1].cognition.memories==1 and loaded.organisms[1].cognition.relationships['900'].trust==.5)
  local restored=assert(I.restore(I.serialize(o)));assert(restored.id==o.id and restored.age==o.age and restored.cognition.relationships['900'].trust==.5 and G.hash(restored.genome)==G.hash(o.genome))
 end)
end
